-- TGA's own entry assessment (replaces the need for GL Assessment).
--
-- One row per sitting. The paper is generated by the entry-assessment Edge
-- Function from `seed` and stored in `form` WITH its answers, so this table is
-- never readable by the candidate: they reach it only through the function,
-- using a one-time link (token_hash). Staff with admissions/leadership roles
-- can read and mark it. When a sitting is complete and linked to a pupil, its
-- headline result is copied into baseline_assessments so it shows on the pupil
-- record alongside any GL results, for the pupil's own teachers too.
-- Idempotent.

create table if not exists public.entry_assessments (
  id uuid primary key default gen_random_uuid(),
  application_id uuid references public.admissions_applications(id) on delete set null,
  child_id uuid references public.children(id) on delete set null,
  candidate_name text not null check (char_length(candidate_name) between 1 and 160),
  year int not null check (year between 1 and 11),
  dob date,
  eal boolean not null default false,
  send_notes text check (send_notes is null or char_length(send_notes) <= 3000),
  access jsonb not null default '{}'::jsonb,
  seed bigint not null,
  form jsonb not null,
  token_hash text unique,
  expires_at timestamptz not null default now() + interval '14 days',
  status text not null default 'issued' check (status in ('issued', 'in_progress', 'submitted', 'complete', 'void')),
  section_index int not null default 0,
  section_started_at timestamptz,
  sections_log jsonb not null default '[]'::jsonb,
  responses jsonb not null default '{}'::jsonb,
  events jsonb not null default '[]'::jsonb,
  marks jsonb not null default '{}'::jsonb,
  report jsonb,
  cohort jsonb,
  device text check (device is null or char_length(device) <= 300),
  timezone text check (timezone is null or char_length(timezone) <= 80),
  invigilator text check (invigilator is null or char_length(invigilator) <= 120),
  notes text check (notes is null or char_length(notes) <= 4000),
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  started_at timestamptz,
  submitted_at timestamptz,
  completed_at timestamptz,
  updated_at timestamptz not null default now()
);
create index if not exists entry_assessments_app_idx on public.entry_assessments (application_id);
create index if not exists entry_assessments_child_idx on public.entry_assessments (child_id);
create index if not exists entry_assessments_status_idx on public.entry_assessments (status, created_at desc);

alter table public.entry_assessments enable row level security;
drop policy if exists "entry_assessments: staff read" on public.entry_assessments;
create policy "entry_assessments: staff read" on public.entry_assessments
  for select to authenticated
  using (public.current_has_role(array['head_teacher', 'admin', 'admissions']));
-- Writes go through the Edge Function (service role), which re-checks roles.

drop trigger if exists entry_assessments_audit on public.entry_assessments;
create trigger entry_assessments_audit
  after insert or update or delete on public.entry_assessments
  for each row execute function public.audit_row_change();

-- baseline_assessments can now hold TGA's own results.
alter table public.baseline_assessments drop constraint if exists baseline_assessments_test_check;
alter table public.baseline_assessments add constraint baseline_assessments_test_check
  check (test in ('CAT4', 'NGRT', 'PTE', 'PTM', 'Baseline interview', 'Other', 'TGA entry assessment'));
alter table public.baseline_assessments add column if not exists details jsonb;
alter table public.baseline_assessments add column if not exists entry_assessment_id uuid references public.entry_assessments(id) on delete cascade;
create unique index if not exists baseline_assessments_entry_uidx on public.baseline_assessments (entry_assessment_id) where entry_assessment_id is not null;

-- Copy a complete sitting onto the pupil record (headline only: per-area
-- working-at levels, groups and the summary; not the answers).
create or replace function public.entry_assessment_sync_baseline(p_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  ea public.entry_assessments;
begin
  select * into ea from public.entry_assessments where id = p_id;
  if ea.id is null or ea.child_id is null or ea.report is null or ea.status <> 'complete' then
    return;
  end if;
  insert into public.baseline_assessments (child_id, provider, test, taken_on, notes, source, details, entry_assessment_id)
  values (
    ea.child_id, 'Tarbiyyah Global Academy', 'TGA entry assessment', coalesce(ea.submitted_at, ea.completed_at, now())::date,
    left(array_to_string(array(select jsonb_array_elements_text(ea.report->'summary')), E'\n'), 2000),
    'manual',
    jsonb_build_object('estimates', ea.report->'estimates', 'writing', ea.report->'writing', 'quran', ea.report->'quran', 'arabic', ea.report->'arabic', 'recommendations', ea.report->'recommendations', 'year', ea.year),
    ea.id
  )
  on conflict (entry_assessment_id) where entry_assessment_id is not null
  do update set child_id = excluded.child_id, taken_on = excluded.taken_on, notes = excluded.notes, details = excluded.details, updated_at = now();
end;
$$;
revoke all on function public.entry_assessment_sync_baseline(uuid) from public, anon, authenticated;

create or replace function public.entry_assessments_after_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.status = 'complete' and new.child_id is not null then
    perform public.entry_assessment_sync_baseline(new.id);
  end if;
  return new;
end;
$$;
drop trigger if exists entry_assessments_sync on public.entry_assessments;
create trigger entry_assessments_sync
  after insert or update of status, child_id, report on public.entry_assessments
  for each row execute function public.entry_assessments_after_change();

-- When an applicant becomes a pupil, their entry assessment follows them.
create or replace function public.admissions_link_entry_assessment()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.child_id is not null and (old.child_id is distinct from new.child_id) then
    update public.entry_assessments set child_id = new.child_id, updated_at = now()
    where application_id = new.id and (child_id is null or child_id = old.child_id);
  end if;
  return new;
end;
$$;
drop trigger if exists admissions_link_entry_assessment on public.admissions_applications;
create trigger admissions_link_entry_assessment
  after update of child_id on public.admissions_applications
  for each row execute function public.admissions_link_entry_assessment();
